CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '' CHECK (length(display_name)<=100), canvas jsonb NOT NULL DEFAULT '{"depth":"Deep","undertone":"Neutral"}', analytics_consent boolean NOT NULL DEFAULT false);
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile ON public.profiles FOR ALL TO authenticated USING (id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(new.id,left(coalesce(new.raw_user_meta_data->>'display_name',''),100)); RETURN new; END $$;
CREATE TRIGGER create_profile_after_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile();
CREATE TABLE public.user_roles (user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('creator','brand')), PRIMARY KEY(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_workspace_role(kind text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role=kind) $$;
CREATE FUNCTION public.join_workspace(kind text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR kind NOT IN ('creator','brand') THEN RAISE EXCEPTION 'Invalid workspace'; END IF; INSERT INTO public.user_roles(user_id,role) VALUES(auth.uid(),kind) ON CONFLICT DO NOTHING; END $$;
REVOKE ALL ON FUNCTION public.join_workspace(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.join_workspace(text) TO authenticated;
REVOKE ALL ON FUNCTION public.has_workspace_role(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_workspace_role(text) TO authenticated;
CREATE TABLE public.content_drafts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, title text NOT NULL CHECK(length(title) BETWEEN 1 AND 160), caption text NOT NULL DEFAULT '' CHECK(length(caption)<=2000), category text NOT NULL CHECK(category IN ('Product','Hair','Skin','Nails','Brows','Makeup')), disclosure text NOT NULL DEFAULT 'Not sponsored' CHECK(disclosure IN ('Not sponsored','Paid partnership','Own product')), product_name text NOT NULL DEFAULT '' CHECK(length(product_name)<=160), license_available boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.content_drafts TO authenticated; GRANT ALL ON public.content_drafts TO service_role;
ALTER TABLE public.content_drafts ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_content ON public.content_drafts FOR ALL TO authenticated USING(owner_id=auth.uid() AND public.has_workspace_role('creator')) WITH CHECK(owner_id=auth.uid() AND public.has_workspace_role('creator'));
CREATE TABLE public.business_products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, name text NOT NULL CHECK(length(name) BETWEEN 1 AND 160), category text NOT NULL CHECK(category IN ('Skincare','Hair','Makeup','Nails','Body')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.business_products TO authenticated; GRANT ALL ON public.business_products TO service_role;
ALTER TABLE public.business_products ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_products ON public.business_products FOR ALL TO authenticated USING(owner_id=auth.uid() AND (public.has_workspace_role('creator') OR public.has_workspace_role('brand'))) WITH CHECK(owner_id=auth.uid() AND (public.has_workspace_role('creator') OR public.has_workspace_role('brand')));
CREATE TABLE public.license_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), brand_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, creator_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, content_id uuid NOT NULL REFERENCES public.content_drafts(id) ON DELETE CASCADE, usage text NOT NULL CHECK(length(usage) BETWEEN 1 AND 500), duration_days integer NOT NULL CHECK(duration_days BETWEEN 1 AND 365), budget numeric NOT NULL CHECK(budget>0), status text NOT NULL DEFAULT 'requested' CHECK(status IN ('requested','accepted','declined')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.license_requests TO authenticated; GRANT ALL ON public.license_requests TO service_role;
ALTER TABLE public.license_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY involved_requests ON public.license_requests FOR SELECT TO authenticated USING(brand_id=auth.uid() OR creator_id=auth.uid());
CREATE FUNCTION public.licensing_catalog() RETURNS TABLE(id uuid,creator_id uuid,title text,category text,product_name text,display_name text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT c.id,c.owner_id,c.title,c.category,c.product_name,p.display_name FROM public.content_drafts c JOIN public.profiles p ON p.id=c.owner_id WHERE c.license_available AND public.has_workspace_role('brand') $$;
CREATE FUNCTION public.request_license(content uuid,requested_usage text,days integer,offered_budget numeric) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE creator uuid; BEGIN IF NOT public.has_workspace_role('brand') THEN RAISE EXCEPTION 'Brand workspace required'; END IF; SELECT owner_id INTO creator FROM public.content_drafts WHERE id=content AND license_available; IF creator IS NULL OR creator=auth.uid() THEN RAISE EXCEPTION 'Content unavailable'; END IF; INSERT INTO public.license_requests(brand_id,creator_id,content_id,usage,duration_days,budget) VALUES(auth.uid(),creator,content,requested_usage,days,offered_budget); END $$;
CREATE FUNCTION public.respond_license(request_id uuid,decision text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF decision NOT IN ('accepted','declined') THEN RAISE EXCEPTION 'Invalid decision'; END IF; UPDATE public.license_requests SET status=decision WHERE id=request_id AND creator_id=auth.uid() AND status='requested'; IF NOT FOUND THEN RAISE EXCEPTION 'Request unavailable'; END IF; END $$;
REVOKE ALL ON FUNCTION public.licensing_catalog(),public.request_license(uuid,text,integer,numeric),public.respond_license(uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.licensing_catalog(),public.request_license(uuid,text,integer,numeric),public.respond_license(uuid,text) TO authenticated;